package com.example.schoolquery.engine;

import com.example.schoolquery.metadata.MetadataRegistry;
import com.example.schoolquery.model.SysModule;
import com.example.schoolquery.model.SysModuleField;
import org.jooq.DSLContext;
import org.jooq.SQLDialect;
import org.jooq.impl.DSL;
import org.junit.jupiter.api.Test;
import java.sql.Connection;
import java.sql.DriverManager;
import java.util.List;
import java.util.Map;
import static org.junit.jupiter.api.Assertions.*;

class ModuleSqlEngineTest {
    private MetadataRegistry registry(){return new MetadataRegistry(List.of(new SysModule(1,"student","学生","student",0)),List.of(new SysModuleField(101,1,"student","id","ID",1),new SysModuleField(102,1,"student","name","姓名",2),new SysModuleField(103,1,"student","age","年龄",3),new SysModuleField(104,1,"student","name","姓名别名",4)),List.of());}
    private DSLContext dsl() throws Exception {Connection connection=DriverManager.getConnection("jdbc:h2:mem:module_sql;DATABASE_TO_UPPER=FALSE;DB_CLOSE_DELAY=-1");connection.createStatement().execute("create table if not exists student (id int generated by default as identity primary key, name varchar(100), age int)");connection.createStatement().execute("delete from student");connection.createStatement().execute("insert into student (id,name,age) values (1, 'Alice', 17), (2, 'Bob', 20), (3, 'Carol', 30)");connection.createStatement().execute("alter table student alter column id restart with 100");return DSL.using(connection,SQLDialect.H2);}
    @Test void executesModuleSqlWithoutLimitAndWithOr() throws Exception {ModuleQueryResult result=new DefaultModuleSqlEngine(registry()).executeQuery(dsl(),"select f101, f102 from module(1) where f102 = 'Alice' or f103 >= 30 order by f101");assertEquals(2,result.rows().size());Map<?,?> root=(Map<?,?>)result.rows().get(0).get("1");assertEquals("Alice",((Map<?,?>)root.get("student")).get("f102"));root=(Map<?,?>)result.rows().get(1).get("1");assertEquals("Carol",((Map<?,?>)root.get("student")).get("f102"));}
    @Test void executesExactOffset() throws Exception {ModuleQueryResult result=new DefaultModuleSqlEngine(registry()).executeQuery(dsl(),"select f101, f102 from module(1) order by f101 limit 1 offset 1");assertEquals(1,result.rows().size());Map<?,?> root=(Map<?,?>)result.rows().get(0).get("1");assertEquals(2,((Map<?,?>)root.get("student")).get("f101"));}
    @Test void metadataPreservesProjectionAliases() {DefaultModuleSqlEngine engine=new DefaultModuleSqlEngine(registry());List<ColumnMeta> metadata=engine.getMetadata("select f101 as studentId, f102 name from module(1)");assertEquals(List.of("studentId","name"),metadata.stream().map(ColumnMeta::columnAlias).toList());assertEquals(List.of(101L,102L),metadata.stream().map(ColumnMeta::fieldId).toList());}
    @Test void duplicateFieldProjectionKeepsEachAliasOccurrence() throws Exception {ModuleQueryResult result=new DefaultModuleSqlEngine(registry()).executeQuery(dsl(),"select f102 as firstName, f102 as secondName from module(1) where f101 = 1");Map<?,?> root=(Map<?,?>)result.rows().get(0).get("1");Map<?,?> student=(Map<?,?>)root.get("student");assertEquals("Alice",student.get("firstName"));assertEquals("Alice",student.get("secondName"));}
    @Test void differentFieldIdsSharingPhysicalColumnUseUniqueLogicalAliases() throws Exception {DefaultModuleSqlEngine engine=new DefaultModuleSqlEngine(registry());ModuleQueryResult result=engine.executeQuery(dsl(),"select f102, f104 from module(1) where f101 = 1");Map<?,?> student=(Map<?,?>)result.rows().get(0).get("1");Map<?,?> values=(Map<?,?>)student.get("student");assertEquals("Alice",values.get("f102"));assertEquals("Alice",values.get("f104"));List<ColumnMeta> metadata=engine.getMetadata("select f102, f104 from module(1)");assertEquals(List.of("f102","f104"),metadata.stream().map(ColumnMeta::columnAlias).toList());assertEquals(List.of(102L,104L),metadata.stream().map(ColumnMeta::fieldId).toList());}
    @Test void duplicateExplicitAliasIsRejected() {DefaultModuleSqlEngine engine=new DefaultModuleSqlEngine(registry());assertThrows(IllegalArgumentException.class,()->engine.getMetadata("select f101 as x, f102 as X from module(1)"));}
    @Test void scalarInsertReturnsGeneratedKey() throws Exception {DSLContext dsl=dsl();ModuleUpdateResult result=new DefaultModuleSqlEngine(registry()).executeUpdate(dsl,"insert into module(1) (f102, f103) values ('Dave', 22)");assertEquals(1,result.affectedRows());assertEquals(1,result.generatedKeys().size());assertNotNull(result.generatedKeys().get(0));assertEquals(100,result.generatedKeys().get(0));}
    @Test void scalarInsertAcceptsModuleCode() throws Exception {DSLContext dsl=dsl();ModuleUpdateResult result=new DefaultModuleSqlEngine(registry()).executeUpdate(dsl,"insert into module('student') (f102, f103) values ('Erin', 23)");assertEquals(1,result.affectedRows());assertEquals(1,result.generatedKeys().size());assertNotNull(result.generatedKeys().get(0));assertEquals(100,result.generatedKeys().get(0));}
    @Test void scalarUpdateAndDeleteUseFieldIdentifiers() throws Exception {DSLContext dsl=dsl();ModuleSqlEngine engine=new DefaultModuleSqlEngine(registry());assertEquals(1,engine.executeUpdate(dsl,"update module(1) set f102 = 'Bobby', f103 = 21 where f101 = 2").affectedRows());assertEquals(1,engine.executeUpdate(dsl,"delete from module(1) where f101 = 3").affectedRows());assertEquals(2,dsl.fetchCount(DSL.table("student")));assertEquals("Bobby",dsl.select(DSL.field("name")).from(DSL.table("student")).where(DSL.field("id").eq(2)).fetchOne(DSL.field("name")));}
    @Test void scalarDmlSupportsComparisonInBetweenNullAndLikePredicates() throws Exception {DSLContext dsl=dsl();ModuleSqlEngine engine=new DefaultModuleSqlEngine(registry());assertEquals(2,engine.executeUpdate(dsl,"update module(1) set f103 = 99 where f103 >= 20 and f103 < 31").affectedRows());assertEquals(2,engine.executeUpdate(dsl,"update module(1) set f102 = 'Matched' where f101 in (1, 3)").affectedRows());assertEquals(2,engine.executeUpdate(dsl,"update module(1) set f102 = 'Between' where f103 between 98 and 100").affectedRows());assertEquals(0,engine.executeUpdate(dsl,"delete from module(1) where f102 is null").affectedRows());assertEquals(2,engine.executeUpdate(dsl,"delete from module(1) where f102 like 'B%'").affectedRows());}
    @Test void scalarDmlPreservesOrSemantics() throws Exception {DSLContext dsl=dsl();ModuleSqlEngine engine=new DefaultModuleSqlEngine(registry());assertEquals(2,engine.executeUpdate(dsl,"update module(1) set f103 = 88 where f101 = 1 or f101 = 3").affectedRows());assertEquals(88,dsl.select(DSL.field("age")).from(DSL.table("student")).where(DSL.field("id").eq(1)).fetchOne(DSL.field("age")));assertEquals(88,dsl.select(DSL.field("age")).from(DSL.table("student")).where(DSL.field("id").eq(3)).fetchOne(DSL.field("age")));assertEquals(20,dsl.select(DSL.field("age")).from(DSL.table("student")).where(DSL.field("id").eq(2)).fetchOne(DSL.field("age")));}
}
